package br.com.devedores.app;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
public class CalendarActivity extends Activity{
 DataStore ds;LinearLayout root;long selected;
 public void onCreate(Bundle b){super.onCreate(b);ds=new DataStore(this);selected=System.currentTimeMillis();build();}
 void build(){root=Ui.col(this);setContentView(root);TextView h=Ui.text(this,"Calendário de vencimentos",24);h.setTypeface(null,1);root.addView(h);CalendarView cal=new CalendarView(this);cal.setDate(selected,false,true);cal.setOnDateChangeListener((v,y,m,d)->{Calendar c=Calendar.getInstance();c.set(y,m,d,0,0,0);c.set(Calendar.MILLISECOND,0);selected=c.getTimeInMillis();render(c);});root.addView(cal,new LinearLayout.LayoutParams(-1,Ui.dp(this,310)));render(Calendar.getInstance());}
 void render(Calendar day){while(root.getChildCount()>2)root.removeViewAt(2);String key=new SimpleDateFormat("dd/MM/yyyy",Locale.getDefault()).format(day.getTime());root.addView(Ui.text(this,"Eventos em "+key,19));boolean any=false;for(Models.Client c:ds.clients)for(Models.Loan l:c.loans)for(int i=0;i<l.installments;i++){long d=l.dueAt(i);String dk=new SimpleDateFormat("dd/MM/yyyy",Locale.getDefault()).format(new Date(d));if(key.equals(dk)){any=true;String st=l.installmentPaid(i)?"✅ Paga":d<System.currentTimeMillis()?"🔴 Atrasada":"🟡 Pendente";root.addView(Ui.text(this,c.name+" • "+l.title+" • parcela "+(i+1)+"\nR$ "+String.format(Locale.getDefault(),"%.2f",l.installmentAmount)+" • "+st,15));}}for(Models.Reminder r:ds.reminders){String rk=new SimpleDateFormat("dd/MM/yyyy",Locale.getDefault()).format(new Date(r.when));if(key.equals(rk)){any=true;root.addView(Ui.text(this,"🔔 "+r.title+"\n"+r.details,15));}}if(!any)root.addView(Ui.text(this,"Nenhum evento neste dia.",15));}
}
